-- Clean bootstrap 005: interaction metrics schema only.
CREATE TABLE IF NOT EXISTS public.user_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,session_started_at timestamptz NOT NULL DEFAULT now(),session_ended_at timestamptz,ip_address inet,user_agent text,device_type text,status text NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS public.screen_views(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,session_id uuid REFERENCES public.user_sessions(id) ON DELETE CASCADE,screen_name text NOT NULL,viewed_at timestamptz NOT NULL DEFAULT now(),duration_seconds integer CHECK(duration_seconds>=0));
CREATE TABLE IF NOT EXISTS public.feature_usage_stats(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,feature_name text NOT NULL,module_name text NOT NULL,usage_count bigint NOT NULL DEFAULT 0,last_used_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,feature_name));
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['user_sessions','screen_views','feature_usage_stats'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('DROP POLICY IF EXISTS metrics_own ON public.%I',t); EXECUTE format('CREATE POLICY metrics_own ON public.%I FOR SELECT TO authenticated USING(public.is_admin() OR user_id=auth.uid())',t); END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.update_feature_usage_stats(p_user_id uuid,p_feature_name text,p_module_name text,p_action_type text DEFAULT NULL,p_time_seconds integer DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR (auth.uid()<>p_user_id AND NOT public.is_admin()) THEN RAISE EXCEPTION 'Metrics access denied' USING ERRCODE='42501'; END IF; INSERT INTO public.feature_usage_stats(user_id,feature_name,module_name,usage_count,last_used_at) VALUES(p_user_id,p_feature_name,p_module_name,1,now()) ON CONFLICT(user_id,feature_name) DO UPDATE SET usage_count=feature_usage_stats.usage_count+1,module_name=EXCLUDED.module_name,last_used_at=now(); END $$;
CREATE OR REPLACE FUNCTION public.get_user_productivity_metrics(p_user_id uuid,p_start_date timestamptz,p_end_date timestamptz) RETURNS TABLE(total_sessions bigint,total_session_time_minutes numeric,avg_session_duration_minutes numeric,total_screens_visited bigint,unique_screens_count bigint,most_used_feature text,most_visited_screen text,productivity_score numeric) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR (auth.uid()<>p_user_id AND NOT public.is_admin()) THEN RAISE EXCEPTION 'Metrics access denied' USING ERRCODE='42501'; END IF; RETURN QUERY SELECT (SELECT count(*) FROM public.user_sessions s WHERE s.user_id=p_user_id AND s.session_started_at BETWEEN p_start_date AND p_end_date),(SELECT COALESCE(sum(extract(epoch FROM (COALESCE(s.session_ended_at,now())-s.session_started_at))/60),0) FROM public.user_sessions s WHERE s.user_id=p_user_id AND s.session_started_at BETWEEN p_start_date AND p_end_date),(SELECT COALESCE(avg(extract(epoch FROM (COALESCE(s.session_ended_at,now())-s.session_started_at))/60),0) FROM public.user_sessions s WHERE s.user_id=p_user_id AND s.session_started_at BETWEEN p_start_date AND p_end_date),(SELECT count(*) FROM public.screen_views v WHERE v.user_id=p_user_id AND v.viewed_at BETWEEN p_start_date AND p_end_date),(SELECT count(DISTINCT v.screen_name) FROM public.screen_views v WHERE v.user_id=p_user_id AND v.viewed_at BETWEEN p_start_date AND p_end_date),(SELECT f.feature_name FROM public.feature_usage_stats f WHERE f.user_id=p_user_id ORDER BY f.usage_count DESC LIMIT 1),(SELECT v.screen_name FROM public.screen_views v WHERE v.user_id=p_user_id AND v.viewed_at BETWEEN p_start_date AND p_end_date GROUP BY v.screen_name ORDER BY count(*) DESC LIMIT 1),least(100,(SELECT count(*)*5 FROM public.screen_views v WHERE v.user_id=p_user_id AND v.viewed_at BETWEEN p_start_date AND p_end_date)::numeric); END $$;
CREATE OR REPLACE FUNCTION public.get_all_users_summary(p_start_date timestamptz) RETURNS TABLE(user_id uuid,full_name text,role text,email text,total_sessions bigint,productivity_score numeric) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'Admin role required' USING ERRCODE='42501'; END IF; RETURN QUERY SELECT p.id,p.full_name,p.role,p.email,(SELECT count(*) FROM public.user_sessions s WHERE s.user_id=p.id AND s.session_started_at>=p_start_date),(SELECT least(100,count(*)*5)::numeric FROM public.screen_views v WHERE v.user_id=p.id AND v.viewed_at>=p_start_date) FROM public.user_profiles p; END $$;
